		return grid[0][0]
	}
	// 若行列索引越界，则返回 +∞ 代价
	if i < 0 || j < 0 {
		return math.MaxInt
	}
	// 若已有记录，则直接返回
	if mem[i][j] != -1 {
		return mem[i][j]
	}
	// 左边和上边单元格的最小路径代价
